import{_ as e,a as i,c as s,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Django ORM、表单约束与事务","description":"区分QuerySet求值、模型迁移、输入校验及数据库原子性。","frontmatter":{"title":"Django ORM、表单约束与事务","description":"区分QuerySet求值、模型迁移、输入校验及数据库原子性。","showdocs":{"topics":[{"id":"python","title":"Python","link":"/topics/python/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Django专题","summary":"区分QuerySet求值、模型迁移、输入校验及数据库原子性。","status":"active","related":[{"title":"Django 入门：项目、路由与请求链","link":"/programming/python/django-request-model","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django常见故障的定位顺序","link":"/programming/python/plus/troubleshooting/django-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践","link":"/programming/python/plus/practice/django-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · Django任务板完整工程包含哪些文件至全部工程文件与同源正文","link":"/programming/python/plus/practice/django-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · tasks/admin.py至版本与资料边界","link":"/programming/python/plus/practice/django-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Django个人任务板完整实践","link":"/programming/python/plus/practice/django-application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Django个人任务板完整实践","link":"/programming/python/plus/practice/django-application"}},"headers":[],"relativePath":"programming/python/plus/subjects/django-data.md","filePath":"programming/python/plus/subjects/django-data.md"}'),n={name:"programming/python/plus/subjects/django-data.md"};function r(o,a,p,l,h,d){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="django-orm、表单约束与事务" tabindex="-1">Django ORM、表单约束与事务 <a class="header-anchor" href="#django-orm、表单约束与事务" aria-label="Permalink to &quot;Django ORM、表单约束与事务&quot;">​</a></h1><p>本文用登录用户的个人任务板解释Task、owner和表单保存；模型、手写迁移、TaskForm及views.py均见<a href="/programming/python/plus/practice/django-application#source-files">完整工程</a>。前置是QuerySet过滤、表单提交与基本数据库约束。</p><p>适用：Python 3.12、Django 5.2.18（5.2 LTS）。先掌握函数、模块、虚拟环境和 HTTP 的请求/响应。示例未执行；本轮不安装依赖、不启动服务、不运行框架或迁移。</p><h2 id="queryset-lazy" tabindex="-1">Django的QuerySet何时真正查询 <a class="header-anchor" href="#queryset-lazy" aria-label="Permalink to &quot;Django的QuerySet何时真正查询 {#queryset-lazy}&quot;">​</a></h2><p><code>filter</code> 返回惰性 QuerySet，链式过滤主要是在构造 SQL；迭代、转成 list、判断真假等会触发求值。不要把“定义一个变量”当作已经获得数据库快照。同一 QuerySet 普通完整迭代后可用结果缓存，重新构造的查询不是同一缓存；需要最新数据应重新查询或刷新实例。</p><p>列表页面把 owner 过滤后的 QuerySet 交给模板，在循环时获取数据；这里不访问 owner 的属性，因此没有因逐行访问关联对象而产生的 N+1。若以后展示用户名，可用 <code>select_related(&quot;owner&quot;)</code> 一起取得外键对象；多对多或反向关系再考虑 <code>prefetch_related</code>。先确定实际访问路径，再测 SQL 次数。</p><h2 id="migration-state" tabindex="-1">Django模型修改后为什么还要迁移 <a class="header-anchor" href="#migration-state" aria-label="Permalink to &quot;Django模型修改后为什么还要迁移 {#migration-state}&quot;">​</a></h2><p>模型代码描述目标模型状态，迁移记录描述状态变化，数据库保存真实表结构。只改 models.py 不会自动改表。本例手写 0001_initial，声明对可替换用户模型的依赖，并创建外键和唯一约束；它不是框架生成或执行成功的证据。</p><p>未来自行运行 <code>makemigrations --check --dry-run</code> 检查模型与迁移状态是否漂移，再用 <code>showmigrations</code> 和 <code>migrate --plan</code> 审阅计划；确认备份后再应用迁移。不要删迁移文件来“修复”已上线数据库。数据迁移应使用历史模型 <code>apps.get_model</code>，并考虑反向操作、分批处理和兼容旧程序的发布顺序。</p><h2 id="form-constraint" tabindex="-1">Django表单校验和数据库约束如何配合 <a class="header-anchor" href="#form-constraint" aria-label="Permalink to &quot;Django表单校验和数据库约束如何配合 {#form-constraint}&quot;">​</a></h2><p>ModelForm 负责把输入转换成 Python 值并校验长度与必填；<code>clean_title</code> 再去掉两端空白。数据库唯一约束保证同一 owner 下 title 唯一，即使两个请求同时通过前置校验，数据库仍是最终裁判。不同用户可以有同名任务，大小写比较语义受数据库排序规则影响，本例不承诺跨数据库完全一致。</p><p>本例 owner 不在表单字段中，组合唯一约束不会依靠用户可编辑 owner 来校验；保存时捕获 IntegrityError 并返回非字段错误。<code>save(commit=False)</code> 只返回未保存实例，赋值 owner 后仍需 save。直接 ORM <code>save</code> 不会自动完整执行表单校验；批量 update 也不会运行模型 save 方法或其信号。</p><h2 id="atomic-boundary" tabindex="-1">Django捕获IntegrityError应该放在哪里 <a class="header-anchor" href="#atomic-boundary" aria-label="Permalink to &quot;Django捕获IntegrityError应该放在哪里 {#atomic-boundary}&quot;">​</a></h2><p>将 <code>try/except IntegrityError</code> 放在 <code>with transaction.atomic()</code> 外部，让异常先离开 atomic 并触发回滚，再处理表单错误。若在仍被标记为失败的事务里继续查询，可能再遇到事务管理错误。atomic 保证这段数据库操作全成或全败，不保证跨网络动作一起回滚。</p><p>本例只有一次保存也明确展示事务边界，为重复标题提供可解释的恢复路径。需要提交后触发通知时使用 <code>transaction.on_commit</code>，同时另行处理通知失败；不要在事务中等待慢网络调用。SQLite 的并发写能力有限，本课程不把它的行为当作 PostgreSQL 行锁模型，也不声称 atomic 等同防止全部竞态。</p><h2 id="orm-example" tabindex="-1">查询写法和可观察结果 <a class="header-anchor" href="#orm-example" aria-label="Permalink to &quot;查询写法和可观察结果 {#orm-example}&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 片段示意，假定已在Django上下文中取得current_user；本轮未执行。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pending </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Task.objects.filter(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">owner</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current_user, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">done</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">titles </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pending.values_list(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">flat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">changed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Task.objects.filter(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">owner</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current_user, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">pk</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task_id).update(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">done</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>第一行构造筛选，第二行物化标题列表；第三行直接执行更新并返回匹配行数。<code>changed == 0</code> 只说明没有匹配行，不应据此泄露“任务存在但属于其他人”。update 不经过 TaskForm，也不会自动运行 clean_title。对于本例编辑页面，仍走表单与实例 save，才能统一展示错误。</p><p>如果只需要确认存在，用 exists 表达意图；如果紧接着要读取全部记录，先 exists 再完整读取会多一次往返。需要数量用 count；需要遍历很多行再讨论 iterator 和分页。模板每展示一个任务就读取额外外键，会把一次列表请求变成多次查询，优化要根据实际访问而非盲目增加预加载。</p><h2 id="schema-change" tabindex="-1">修改字段时的发布顺序 <a class="header-anchor" href="#schema-change" aria-label="Permalink to &quot;修改字段时的发布顺序 {#schema-change}&quot;">​</a></h2><p>例如以后增加非空备注字段，现有行没有值，不能只改模型后假定迁移会猜出业务含义。通常先允许空或给出符合业务的默认策略，发布兼容代码，分批补旧数据，再收紧约束。不能为方便随意把所有历史用户数据写成一个无意义常量。</p><p>本例已有唯一约束；若给旧数据库新加同类约束，先查重、确定保留规则并备份，再应用结构变化。大表创建索引和修改列的锁行为依后端而异，SQLite教学不涵盖线上无停机迁移。把源文件入库、检查计划和实际执行三个事实分开记录，才能追踪失败时在哪个阶段。</p><h2 id="exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;独立练习 {#exercise}&quot;">​</a></h2><p>解释两个请求同时创建同一标题时，为什么预先 exists 仍不能保证唯一；把发送邮件放进 atomic 是否能够回滚邮件？</p><p>先写出判断依据，再核对下节。</p><h2 id="answers" tabindex="-1">参考解答 <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;参考解答 {#answers}&quot;">​</a></h2><p>两次检查可能都为否，唯一约束由数据库最终裁决；邮件是外部副作用，不随数据库回滚，应提交后处理且设计失败补偿。</p><h2 id="sources" tabindex="-1">版本与资料边界 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;版本与资料边界 {#sources}&quot;">​</a></h2><p>核对日期2026-10-17。官方5.2.18发布页标注2026-10-06，官方支持表列5.2 LTS扩展支持至2028年4月。这里固定教学补丁，不声称以后仍是最新版本；未来自跑应先检查受支持补丁并重新验收。Windows PowerShell、macOS/Linux Bash/Zsh的命令已在完整工程README分开给出，三平台均未运行。</p><p><a href="https://docs.djangoproject.com/en/5.2/topics/db/queries/" target="_blank" rel="noopener noreferrer">ORM查询</a>；<a href="https://docs.djangoproject.com/en/5.2/topics/migrations/" target="_blank" rel="noopener noreferrer">迁移</a>；<a href="https://docs.djangoproject.com/zh-hans/5.2/topics/db/transactions/" target="_blank" rel="noopener noreferrer">事务（中文）</a>；<a href="https://docs.djangoproject.com/en/5.2/topics/forms/" target="_blank" rel="noopener noreferrer">表单</a>。版本依据：<a href="https://www.djangoproject.com/download/" target="_blank" rel="noopener noreferrer">支持表</a>与<a href="https://docs.djangoproject.com/en/5.2/releases/5.2.18/" target="_blank" rel="noopener noreferrer">5.2.18发布页</a>。</p>`,30)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
